/**
 * ReactionClip — short full-bleed reaction/meme video clip with an optional
 * punchline overlay.
 *
 * Lifted from `reaction.tsx`. The primitive owns:
 *   - the full-frame <video> element (loop + muted + playsInline)
 *   - the dark vertical scrim that keeps text readable over busy footage
 *
 * It does NOT own the SceneBackground gradient/zoom fallback or the
 * headline TemplateText — those stay in the scene composer so brand
 * background + archetype-driven typography can live around the clip.
 *
 * Props:
 *  - progress   — scene progress 0..1 (unused for now; reserved for future
 *                 fade-in/fade-out treatments)
 *  - width      — frame width
 *  - height     — frame height
 *  - videoUrl   — direct MP4 URL (typically a Pexels reaction clip). When
 *                 empty the primitive renders a transparent shell so the
 *                 scene composer's background still shows through.
 *  - punchline  — optional short caption rendered bottom-center. The
 *                 source template lifts this into a full TemplateText
 *                 archetype; the primitive only owns a simple legible
 *                 overlay for self-contained use cases.
 *  - beatIntensity — optional 0..1 audio reactivity (subtle scale pop)
 *  - accent     — brand accent (unused today, accepted for parity with
 *                 sibling social primitives so callers can pass a brand
 *                 kit uniformly)
 */

import * as React from "react";
import { stripPipe } from "../../scene-templates/text-utils";

export interface ReactionClipProps {
  progress: number;
  width: number;
  height: number;
  videoUrl: string;
  punchline?: string;
  beatIntensity?: number;
  accent?: string;
}

export const ReactionClip: React.FC<ReactionClipProps> = ({
  width,
  height,
  videoUrl,
  punchline,
  beatIntensity = 0,
}) => {
  const dim = Math.min(width, height);
  const hasClip = (videoUrl || "").trim().length > 0;
  const text = stripPipe(punchline || "").trim();
  const beatScale = 1 + beatIntensity * 0.01;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor: "#000",
      }}
    >
      {hasClip && (
        <video
          src={videoUrl}
          autoPlay
          loop
          muted
          playsInline
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            objectFit: "cover",
            transform: `scale(${beatScale})`,
          }}
        />
      )}

      {/* Vertical scrim for legibility */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "linear-gradient(180deg, rgba(0,0,0,.18), rgba(0,0,0,.08) 45%, rgba(0,0,0,.5))",
          pointerEvents: "none",
        }}
      />

      {text && (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: dim * 0.1,
            textAlign: "center",
            color: "#ffffff",
            fontSize: dim * 0.07,
            fontWeight: 800,
            letterSpacing: -0.5,
            lineHeight: 1.1,
            textShadow: "0 2px 12px rgba(0,0,0,0.6)",
            padding: `0 ${dim * 0.06}px`,
          }}
        >
          {text}
        </div>
      )}
    </div>
  );
};
